head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gIsurCd;
scwin.gImprRegDd;
scwin.gImprRegDd2; //이행보고서 등록일자
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.vScrenID = 'ULDSTF35102.xml';
scwin.gAllChk = false;
scwin.gConfrmDdtm;
scwin.gConfrmDdtmSubStr;
scwin.gConfrmrEmpNo;
scwin.gPnltSeq;
scwin.gUploadGubun; //개선계획서, 이행보고서 업로드 구분(01: 개선계획서, 02: 이행보고서)

//오늘날짜
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    // 벌점부과유형  셋팅
    dts_ImpostTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=PNLT_IMPOST_TP_CD";
    dts_ImpostTp.Reset();

    // 벌점부과사유  셋팅
    dts_ImpostRsn.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=PNLT_IMPOST_RSN_CD";
    dts_ImpostRsn.Reset();

    // 공시유형 셋팅
    dts_DisclsTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=DISCLS_TP_CD";
    dts_DisclsTp.Reset();

    // 시장조치예고  셋팅
    dts_AdvnotiTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=MKTACT_ADVNOTI_TP_CD";
    dts_AdvnotiTp.Reset();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !벌점--;
클릭-- > function() {
    // 법인코드 자리수 체크 
    if ($c.stf.getObjectValue(txb_isur_cd).length != 5) {
        $c.win.alert("회사코드 5자리를 올바르게 입력하십시오.");
        txb_isur_cd.focus();
        return;
    }
    scwin.fn_Clear();

    // 1. 벌점부과현황 조회
    var url = "/PenaltyImposition.do?method=readPenaltyStatInfo&inputMessageId=PNLTINFO_INOUT" + "&outputMessageId=PNLTINFO_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&LD_MKT_TP=1" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //  데이타 조회
    dts_pnltsat_info.DataID = encodeURI(url);
    dts_pnltsat_info.reset();

    // 2. 벌점부과 상세내역
    //txb_TotalCnt.value = "총건수 : " ;	
    var url_list = "/PenaltyImposition.do?method=listPenaltyHistory&inputMessageId=PNLTINFO_INOUT" + "&outputMessageId=PNLTDTLLIST_OUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&LD_MKT_TP=1";

    //  데이타 조회
    dts_pnlt_history.DataID = encodeURI(url_list);
    dts_pnlt_history.reset();


    // 3. 개선계획서 조회
    var url_file = "/PenaltyImposition.do?method=readPnltImprSchdlInfo&inputMessageId=IMPRSCHDLFILE_INOUT" + "&outputMessageId=IMPRSCHDLFILE_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);

    //  데이타 조회
    dts_imprschdl_file.DataID = encodeURI(url_file);
    dts_imprschdl_file.reset();

    // 4. 이행보고서 조회
    var url_file = "/PenaltyImposition.do?method=readPnltImprPerfmDtlInfo&inputMessageId=IMPRSCHDLFILE_INOUT" + "&outputMessageId=IMPRSCHDLFILE_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);

    //  데이타 조회
    dts_imprschdl_file2.DataID = encodeURI(url_file);
    dts_imprschdl_file2.reset();
};




// 다음버튼 클릭시 누적벌점 계산
scwin.fn_GetSumPnlt = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isurcd);
    if (vIsurCd == "") {
        $c.win.alert("회사를 선택하세요.");
        txb_isur_cd.focus();
        return false;
    }
    var vToday = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(edt_impost_dd) < vToday) {
        $c.win.alert("벌점부과일에는 오늘 이후의 날짜만 입력할 수 있습니다");
        edt_impost_dd.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_rsnoccr_dd) == "") {
        $c.win.alert("사유발생일을 입력하십시오");
        edt_rsnoccr_dd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ImpostTp) == "") {
        $c.win.alert("벌점부과유형을 선택하십시오");
        cmb_ImpostTp.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ImpostRsn) == "") {
        $c.win.alert("벌점부과사유를 선택하십시오");
        cmb_ImpostRsn.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DisclsTp) == "") {
        $c.win.alert("공시유형을 선택하십시오");
        cmb_DisclsTp.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_pnlt) == "") {
        $c.win.alert("벌점을 입력하십시오");
        txb_pnlt.focus();
        return false;
    }
    if (scwin.isNumJum($c.stf.getObjectValue(txb_pnlt)) == false) {
        $c.win.alert("숫자만 입력가능합니다.");
        txb_pnlt.focus();
        return false;
    }
    var url = "/PenaltyImposition.do?method=readEstimatedPenaltySum&inputMessageId=PNLTDATA_INOUT" + "&outputMessageId=PNLTDATA_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isurcd) + "&PNLT_IMPOST_DD=" + $c.stf.getObjectValue(edt_impost_dd) + "&RSN_OCCR_DD=" + $c.stf.getObjectValue(edt_rsnoccr_dd) + "&PNLT=" + $c.stf.getObjectValue(txb_pnlt) + "&LD_MKT_TP=1";

    //  데이타 조회
    dts_pnltsum_info.DataID = encodeURI(url);
    dts_pnltsum_info.reset();
};



// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_pnlt_list.getCellData(eval(obj), "ISUR_CD");

    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.fn_CheckValue = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isurcd);
    if (vIsurCd == "") {
        $c.win.alert("회사 선택후 벌점부과현황을 조회후에 입력처리가 가능합니다.");
        txb_isur_cd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_impost_dd) == "") {
        $c.win.alert("벌점부과일을 입력하십시오");
        edt_impost_dd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_rsnoccr_dd) == "") {
        $c.win.alert("사유발생일을 입력하십시오");
        edt_rsnoccr_dd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ImpostTp) == "") {
        $c.win.alert("벌점부과유형을 선택하십시오");
        cmb_ImpostTp.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ImpostRsn) == "") {
        $c.win.alert("벌점부과사유를 선택하십시오");
        cmb_ImpostRsn.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DisclsTp) == "") {
        $c.win.alert("공시유형을 선택하십시오");
        cmb_DisclsTp.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_pnlt) == "") {
        $c.win.alert("벌점을 입력하십시오");
        txb_pnlt.focus();
        return false;
    }
    if (scwin.isNumJum($c.stf.getObjectValue(txb_pnlt)) == false) {
        $c.win.alert("숫자만 입력가능합니다.");
        txb_pnlt.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_schdl_dd) != '' &&
        $c.stf.getObjectValue(edt_releas_schdl_dd) != '') {
        if ($c.stf.compareFromToDate(edt_schdl_dd, edt_releas_schdl_dd, '관리종목지정일', '관리종목해제예정일') == false) {
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_AdvnotiTp) == "") {
        $c.win.alert("시장조치예고를  선택하십시오");
        cmb_AdvnotiTp.focus();
        return false;
    }
    if (scwin.isNumJum($c.stf.getObjectValue(txb_tot_pnlt)) == false) {
        $c.win.alert("숫자만 입력가능합니다.");
        txb_tot_pnlt.focus();
        return false;
    }
    if (chb_confirm.checked == false) {
        $c.win.alert("담당자확인을 체크해야만 입력 할 수 있습니다");
        chb_confirm.focus();
        return false;
    }
    return true;
};
scwin.isNumJum = function(sVal) {
    if (('0' < sVal) || ('9' > sVal) || ('.' == sVal)) {
        return true;
    } else {
        return false;
    }
};



// 벌점 입력
scwin.fn_Insert = function() {
    if (scwin.fn_CheckValue() == false) {
        return;
    }
    dts_Pnlt_Input.insertRow();
    dts_Pnlt_Input.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_isurcd));
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_DD", $c.stf.getObjectValue(edt_impost_dd));
    dts_Pnlt_Input.setCellData(1, "RSN_OCCR_DD", $c.stf.getObjectValue(edt_rsnoccr_dd));
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_TP_CD", $c.stf.getObjectValue(cmb_ImpostTp));
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_RSN_CD", $c.stf.getObjectValue(cmb_ImpostRsn));
    dts_Pnlt_Input.setCellData(1, "DISCLS_TP_CD", $c.stf.getObjectValue(cmb_DisclsTp));
    dts_Pnlt_Input.setCellData(1, "PNLT", $c.stf.getObjectValue(txb_pnlt));
    dts_Pnlt_Input.setCellData(1, "MKTACT_ADVNOTI_TP_CD", $c.stf.getObjectValue(cmb_AdvnotiTp));
    dts_Pnlt_Input.setCellData(1, "ADMISU_SCHDL_DD", $c.stf.getObjectValue(edt_schdl_dd));
    dts_Pnlt_Input.setCellData(1, "ADMISU_RELEAS_SCHDL_DD", $c.stf.getObjectValue(edt_releas_schdl_dd));
    dts_Pnlt_Input.setCellData(1, "CONFRMR_EMP_NO", scwin.gEmpNo);
    var vAnswer = confirm('벌점 입력처리 하시겠습니까?');
    if (vAnswer == true) {
        trs_Pnlt_Input.Action = "/PenaltyImposition.do?method=registerPenalty&inputMessageId=PNLTDATA_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        trs_Pnlt_Input.KeyValue = "JSP(I:pInput=dts_Pnlt_Input)";
        trs_Pnlt_Input.Post();
    }
};




// 입력항목 clear
scwin.fn_Clear = function() {
    $c.stf.setObjectValue(edt_impost_dd, "");
    $c.stf.setObjectValue(edt_rsnoccr_dd, "");
    $c.stf.setObjectValue(cmb_ImpostTp, "");
    $c.stf.setObjectValue(cmb_ImpostRsn, "");
    $c.stf.setObjectValue(cmb_DisclsTp, "");
    $c.stf.setObjectValue(txb_pnlt, "");
    $c.stf.setObjectValue(edt_schdl_dd, "");
    $c.stf.setObjectValue(edt_releas_schdl_dd, "");
    $c.stf.setObjectValue(cmb_AdvnotiTp, "");
    $c.stf.setObjectValue(txb_tot_pnlt, "");
    $c.stf.setObjectValue(chb_confirm, "");
};


// 개선계획서파일 다운로드
scwin.fn_filedown = function(gubun) {
    //gubun 01:개선계획서, 02:이행보고서

    var vRegDd; //등록일
    var vgubun; //파일다운로드 구분

    if (gubun == "01") {
        //개선계획서
        vRegDd = dts_imprschdl_file.getCellData(1, "IMPR_REG_DD");
        vgubun = "10";
    } else {
        //이행보고서
        vRegDd = dts_imprschdl_file2.getCellData(1, "IMPR_REG_DD");
        vgubun = "33";
    }
    var link = "/filedownload.do?REG_DD=" + vRegDd + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isurcd) + "&gubun=" + vgubun + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08;
    location.href = encodeURI(link);
};


// 개선계획서 삭제
scwin.fn_FileDelete = function(gubun) {
    //gubun 01:개선계획서, 02:이행보고서

    var vRegDd;
    var confirmMsg;
    if (gubun == "01") {
        vRegDd = dts_imprschdl_file.getCellData(1, "IMPR_REG_DD");
        if (txb_filename.getValue() == "") {
            $c.win.alert("삭제할 개선계획서가 없습니다.");
            retrun;
        }
        vRegDd = dts_imprschdl_file.getCellData(1, "IMPR_REG_DD");
        confirmMsg = "개선계획서";
    } else {
        if (txb_filename2.getValue() == "") {
            $c.win.alert("삭제할 이행보고서가 없습니다.");
            retrun;
        }
        vRegDd = dts_imprschdl_file2.getCellData(1, "IMPR_REG_DD");
        confirmMsg = "이행보고서";
    }

    //삭제처리하기전 초기화 해준다.
    dts_imprFile_Delete.removeAll();
    dts_imprFile_Delete.insertRow();
    dts_imprFile_Delete.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_isurcd));
    dts_imprFile_Delete.setCellData(1, "IMPR_REG_DD", vRegDd);
    var vAnswer = confirm(confirmMsg + '를 삭제 하시겠습니까?');
    if (vAnswer == true) {
        if (gubun == "01") {
            trs_FileDelete.Action = "/PenaltyImposition.do?method=removeImprSchdlFile&inputMessageId=IMPRSCHDLFILE_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        } else {
            trs_FileDelete.Action = "/PenaltyImposition.do?method=removeImprPerfmDtlFile&inputMessageId=IMPRSCHDLFILE_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        }

        //trs_FileDelete.Action="/PenaltyImposition.do?method=removeImprSchdlFile&inputMessageId=IMPRSCHDLFILE_INOUT&SCREN_ID=" + vScrenID +"&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_FileDelete.KeyName = "toinb_dataid4";
        trs_FileDelete.KeyValue = "JSP(I:pInput=dts_imprFile_Delete)";
        trs_FileDelete.Post();
    } else {
        dts_imprFile_Delete.removeAll();
    }
};




// 당일 등록한 벌점 입력번호 중 Max 값 구하기
scwin.checkPenalty = function() {
    trs_Read.Action = "/PenaltyImposition.do?method=readMaxPenaltySeq&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_pnlt_seq)";
    trs_Read.Post();
};




// 삭제 버튼 클릭 시
scwin.fn_RowDelelete = function() {
    //gLastJob = "삭제";
    var gCnt = 0;
    var gMaxPlntSeq = $c.stf.getObjectValue(txt_pnlt_seq); // 당일 입력한 데이터중 벌점일련번호가 가장 큰 값

    for (var k = 1; k <= dts_pnlt_history.getTotalRow(); k++) {
        gStat = dts_pnlt_history.getCellData(k, "CHECK");
        scwin.gConfrmDdtm = dts_pnlt_history.getCellData(k, "CONFRM_DDTM"); // 벌점 등록일
        scwin.gConfrmDdtmSubStr = dts_pnlt_history.getCellData(k, "CONFRM_DDTM").substring(0, 8); // 벌점 등록일
        scwin.gConfrmrEmpNo = dts_pnlt_history.getCellData(k, "CONFRMR_EMP_NO"); // 벌점 등록자
        scwin.gPnltSeq = dts_pnlt_history.getCellData(k, "PNLT_SEQ"); // 벌점 일련번호


        if (gStat == "T") {
            gCnt++;

            // 당일 입력한 데이터중에 가장 마지막에 등록한 데이터를 먼저 삭제를 해야함
            // 누적벌점 계산때문에 중간의 데이터를 삭제하지 못함
            if (scwin.gPnltSeq < gMaxPlntSeq) {
                $c.win.alert('당일 마지막 입력건이 존재합니다.\n당일 입력건에 대해서만 삭제가 가능하며\n마지막 입력건을 먼저 삭제 하신 후에 삭제 처리가 가능합니다.');
                return;
            }
        }
    }
    dts_pnlt_history.setBroadcast(true);
    if (gCnt == 0) {
        $c.win.alert("삭제 대상이 체크되지 않았습니다.");
        return;
    }
    if (window.confirm("데이터를 삭제하시겠습니까?")) {
        //if (window.confirm("[총"+gCnt+"건]의 데이터를 삭제하시겠습니까?")) {
        var url = "/PenaltyImposition.do?method=deletePenaltyImposition&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Pnlt_Delete.Action = url;
        trs_Pnlt_Delete.KeyName = "toinb_dataid4";
        trs_Pnlt_Delete.KeyValue = "JSP(I:pInput=dts_pnlt_history)";
        trs_Pnlt_Delete.Post();
    }
};
scwin.grd_pnlt_history_OnCheckClick = function() {
    // 그리드의 체크박스를 라이오버튼 처럼 하나만 선택되게 처리

    scwin.checkPenalty();
    var checkRadio = dts_pnlt_history.getRowPosition();
    dts_pnlt_history.undoAll();
    dts_pnlt_history.setCellData(checkRadio, 'CHECK', 'T');
    for (var k = 1; k <= dts_pnlt_history.getTotalRow(); k++) {
        gStat = dts_pnlt_history.getCellData(k, "CHECK");
        scwin.gConfrmDdtm = dts_pnlt_history.getCellData(k, "CONFRM_DDTM"); // 벌점 등록일
        scwin.gConfrmDdtmSubStr = dts_pnlt_history.getCellData(k, "CONFRM_DDTM").substring(0, 8); // 벌점 등록일
        scwin.gConfrmrEmpNo = dts_pnlt_history.getCellData(k, "CONFRMR_EMP_NO"); // 벌점 등록자
        scwin.gPnltSeq = dts_pnlt_history.getCellData(k, "PNLT_SEQ"); // 벌점 일련번호

        if (gStat == "T") {
            // 당일 데이터만 삭제 가능
            if (scwin.gConfrmDdtmSubStr != scwin.vCurDate) {
                $c.win.alert('과거 데이터는 삭제 할 수 없습니다.');
                dts_pnlt_history.undoAll();
            } else {
                // 본인이 등록한 데이터만 삭제 가능
                if (scwin.gConfrmrEmpNo != scwin.gEmpNo) {
                    $c.win.alert('본인이 입력한 데이터만 삭제 할 수 없습니다.');
                    dts_pnlt_history.undoAll();
                }
            }
        }
    }
};
